/* MINOR INDEX — the atelier's build step.
 *
 * The plate code is CommonJS because node runs it; the atelier is a page
 * because a page is what a hand can hold. This makes the second out of the
 * first so there is one copy of the vocabulary and not two.
 *
 * Each module keeps its own scope — the files are wrapped, not stripped, and
 * given a `require` that resolves to the ones already built. That matters:
 * `_letters.js` has a `G` (the glyph table) and `_mark.js` has a `G` (the SVG
 * group), and in one shared scope one of them would quietly win.
 *
 *   node logo/mkbundle.js            → logo/docs/_bundle.js
 *   node logo/mkbundle.js --inline   → also logo/docs/atelier.html, one file
 */
const fs = require("fs");
const path = require("path");

/* in dependency order */
const SRC = ["_mark.js", "_glyphs.js", "_letters.js", "_font.js", "_studio.js"];
/* what the page gets on window.MINOR */
const EXPOSE = {
  "_mark.js": ["INK", "GROT", "MONO", "n", "rng", "pick", "segDist", "L", "axes", "brackets",
    "trim", "polar", "swipe", "svg", "G"],
  "_glyphs.js": ["blob", "cell", "sunGeom", "sunSolid", "sunSDF", "sunWhirl", "screen",
    "cellGeom", "cellSDF", "phylloPts", "sPts", "sScatter", "spiralPath", "spiralWalls",
    "sSpiral", "sDisc", "sRing", "sBox", "sUnion", "sSub", "sShift", "sTwist", "sGrow",
    "sSmooth", "sMorph", "noise2", "sWobble", "contour", "sBite", "sunBound", "cellBound"],
  "_studio.js": ["PARAMS", "FIELDS", "DEFAULTS", "SHEETS", "INKS", "buildPlate", "emitPlate",
    "rollState", "sheetOf", "visible", "stMetrics", "compactDots"],
};
/* and two namespaces, kept whole */
const NAMESPACES = { text: "_letters.js", font: "_font.js" };

const dir = __dirname;
const wrapped = SRC.map((f) => {
  const src = fs.readFileSync(path.join(dir, f), "utf8");
  return `/* ==== ${f} ${"=".repeat(Math.max(0, 60 - f.length))} */\n`
    + `__MI__[${JSON.stringify(f)}] = (function () {\n`
    + `var module = { exports: {} }, exports = module.exports;\n`
    + `var require = function (p) { return __MI__[p.replace("./", "")]; };\n`
    + src
    + `\nreturn module.exports;\n})();`;
});

const picks = [];
for (const f in EXPOSE) for (const k of EXPOSE[f]) picks.push(`  ${k}: __MI__[${JSON.stringify(f)}].${k},`);
for (const ns in NAMESPACES) picks.push(`  ${ns}: __MI__[${JSON.stringify(NAMESPACES[ns])}],`);

const bundle = `/* MINOR INDEX — generated by mkbundle.js. Do not edit: edit the modules.
   ${SRC.join(" + ")} → one file, each module still in its own scope. */
(function (global) {
"use strict";
var __MI__ = {};   /* the registry, named so no module can shadow it */
${wrapped.join("\n\n")}

global.MINOR = {
${picks.join("\n")}
};
})(typeof window !== "undefined" ? window : globalThis);
`;

const web = path.join(dir, "docs");   /* GitHub Pages serves this folder */
fs.mkdirSync(web, { recursive: true });
fs.writeFileSync(path.join(web, "_bundle.js"), bundle);
console.log(`docs/_bundle.js  ${(bundle.length / 1024).toFixed(0)}kb  (${SRC.join(", ")})`);

if (process.argv.includes("--inline")) {
  const html = fs.readFileSync(path.join(web, "index.html"), "utf8");
  const one = html.replace('<script src="_bundle.js"></script>', `<script>\n${bundle}\n</script>`);
  /* The site serves docs/index.html directly, with _bundle.js beside it. This
     single-file build is for the Claude artifact, which wraps the file in a
     document of its own — so it must not bring a second doctype with it. */
  const artifact = one.replace(/^<!doctype html>\s*/i, "");
  fs.writeFileSync(path.join(web, "atelier.html"), artifact);
  console.log(`docs/atelier.html  ${(artifact.length / 1024).toFixed(0)}kb  (one file, nothing external)`);
}
